# -*- coding: utf-8 -*-
# المرحلة 4: التربية الإسلامية والمهارات الحياتية للصفوف 1-6
import random
from libspecs3 import *
def box(n=12): return f'<span class="opt" style="min-width:{n}mm;height:10mm;vertical-align:middle"></span>'
def order_rows(items):
    return ''.join(f'<div class="bx" style="display:flex;align-items:center;gap:4mm;padding:2mm 5mm">{box()}<span style="font-size:14pt">{t}</span></div>' for t in items)
def mcq(qs):
    return ''.join(f'<div class="bx"><b>{i+1})</b> {q}<br>{chips(o)}</div>' for i, (q, o, _) in enumerate(qs))
def fin(sp, P, keyhtml):
    P.append(('الإجابات النموذجية', 'للمعلّم أو ولي الأمر.', keyhtml, 'key'))
    return sp, P
def S(slug, title, sub, chips_, color, tint):
    return spec(slug=slug, title=title, subtitle=sub, chips=chips_, color=color, tint=tint, note='اطبع الصفحات وأجب عنها، ثم راجع الإجابات في الصفحة الأخيرة.')
def shuf(lst, seed):
    r = random.Random(seed); x = list(lst); r.shuffle(x); return x

# ===== تربية إسلامية =====
def isl1():
    pill = ['النطق بالشهادتين', 'إقامة الصلاة', 'إيتاء الزكاة', 'صوم رمضان', 'حج البيت لمن استطاع']
    body = '<p class="ins">أركان الإسلام خمسة. اقرأها بالترتيب:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center"><span class="no" style="width:10mm;height:10mm;font-size:14pt">{i+1}</span><span style="font-size:15pt;font-weight:700">{p}</span></div>' for i, p in enumerate(pill))
    P = [('أركان الإسلام الخمسة', 'نتعلّم أركان الإسلام ونرتّبها.', body, 'ws')]
    sh = shuf(pill, 3)
    P.append(('أرتّب الأركان', 'اكتب رقم كل ركن في المربع حسب ترتيبه الصحيح (من 1 إلى 5).', order_rows(sh), 'ws'))
    qs = [('كم عدد أركان الإسلام؟', ['ثلاثة', 'خمسة', 'ستة'], 'خمسة'), ('في أي شهر نصوم؟', ['شعبان', 'رمضان', 'رجب'], 'رمضان'), ('كم صلاة نصلّي في اليوم والليلة؟', ['ثلاث', 'أربع', 'خمس'], 'خمس')]
    t = [('الزكاة نعطيها للفقراء والمحتاجين.', 'صح'), ('الحج ركن من أركان الإسلام.', 'صح'), ('نصوم في شهر شوال.', 'خطأ')]
    P.append(('أختار وأحكم', 'ضع دائرة حول الإجابة الصحيحة.', mcq(qs) + tf(t), 'ws'))
    key = '<p><b>صفحة الترتيب:</b> ' + ' ← '.join(f'{i+1}) {p}' for i, p in enumerate(pill)) + '</p>' + K('الاختيار', [a for *_, a in qs]) + K('صح وخطأ', [a for _, a in t]) + '<p>نصوم في شهر رمضان وليس شوال.</p>'
    return fin(S('g1-pillars-of-islam', 'أركان الإسلام', 'أتعرّف على الأركان الخمسة وأرتّبها', ['الصف الأول', 'التربية الإسلامية', 'العقيدة والعبادات', 'مع الحلول'], '#0d9488', '#dcf7f2'), P, key)

def isl2():
    ok = [('أغسل يديّ قبل الطعام.', 'صح'), ('أقول «بسم الله» قبل أن آكل.', 'صح'), ('آكل بيدي اليمنى.', 'صح'), ('أرمي الطعام الزائد ولا أهتمّ.', 'خطأ'), ('أقول «الحمد لله» بعد أن أنتهي.', 'صح'), ('أتكلّم وفمي مليء بالطعام.', 'خطأ')]
    P = [('آداب الطعام', 'اقرأ كل عبارة وحدّد إن كانت من آداب الطعام الصحيحة.', tf(ok), 'ws')]
    steps = ['أغسل يديّ بالماء والصابون', 'أقول «بسم الله» وآكل بيدي اليمنى', 'آكل ممّا يليني وبهدوء', 'أقول «الحمد لله» وأغسل يديّ']
    P.append(('أرتّب خطوات الطعام', 'رقّم الخطوات من 1 إلى 4 بحسب ما نفعله قبل الأكل وأثناءه وبعده.', order_rows(shuf(steps, 5)), 'ws'))
    body = f'<div class="bx" style="font-size:15pt;line-height:2.4">١) نقول قبل الأكل: «{ans_line(30)}».<br>٢) نقول بعد الأكل: «{ans_line(30)}».<br>٣) نأكل بيدنا ال{ans_line(20)}.</div><p class="ins" style="margin-top:4mm">ارسم طعامك المفضّل واكتب اسمه تحت الرسم:</p><div class="q" style="min-height:70mm"></div>'
    P.append(('أكمل وأرسم', 'اكتب الكلمة الناقصة.', body, 'ws'))
    key = K('صح وخطأ', [a for _, a in ok]) + '<p><b>ترتيب الخطوات:</b> ' + ' ← '.join(f'{i+1}) {s}' for i, s in enumerate(steps)) + '</p><p>صفحة الإكمال: (١) بسم الله (٢) الحمد لله (٣) اليمنى. الرسم حرّ.</p>'
    return fin(S('g2-eating-manners', 'آداب الطعام', 'أتعلّم ما نفعله قبل الأكل وأثناءه وبعده', ['الصف الثاني', 'التربية الإسلامية', 'الآداب', 'مع الحلول'], '#ea580c', '#ffeadb'), P, key)

def isl3():
    pil = ['الإيمان بالله', 'الإيمان بالملائكة', 'الإيمان بالكتب', 'الإيمان بالرسل', 'الإيمان باليوم الآخر', 'الإيمان بالقدر خيره وشرّه']
    body = '<p class="ins">أركان الإيمان ستة:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center"><span class="no" style="width:10mm;height:10mm;font-size:14pt">{i+1}</span><span style="font-size:15pt;font-weight:700">{p}</span></div>' for i, p in enumerate(pil))
    P = [('أركان الإيمان الستة', 'نقرأ أركان الإيمان بالترتيب.', body, 'ws')]
    L = ['جبريل عليه السلام', 'القرآن الكريم', 'محمد صلى الله عليه وسلم']; R = ['الإيمان بالرسل', 'الإيمان بالملائكة', 'الإيمان بالكتب']
    # الإجابات: جبريل→الملائكة، القرآن→الكتب، محمد→الرسل
    P.append(('أصِل الاسم بركنه', 'صِل كل اسم بركن الإيمان الذي يتبعه.', line_match(L, R), 'ws'))
    qs = [('كم عدد أركان الإيمان؟', ['أربعة', 'ستة', 'خمسة'], 'ستة'), ('الركن الأول من أركان الإيمان هو الإيمان…', ['بالملائكة', 'بالله', 'بالكتب'], 'بالله'), ('القرآن الكريم هو من…', ['الملائكة', 'الكتب', 'الرسل'], 'الكتب')]
    P.append(('أختار الإجابة', 'ضع دائرة حول الإجابة الصحيحة.', mcq(qs), 'ws'))
    key = '<p><b>الأركان:</b> ' + '، '.join(f'{i+1}) {p}' for i, p in enumerate(pil)) + '</p><p><b>التوصيل:</b> جبريل عليه السلام ← الإيمان بالملائكة، القرآن الكريم ← الإيمان بالكتب، محمد صلى الله عليه وسلم ← الإيمان بالرسل.</p>' + K('الاختيار', [a for *_, a in qs])
    return fin(S('g3-pillars-of-faith', 'أركان الإيمان الستة', 'أحفظ الأركان وأربطها بأمثلة', ['الصف الثالث', 'التربية الإسلامية', 'العقيدة', 'مع الحلول'], '#4f46e5', '#e6e7ff'), P, key)

def isl4():
    steps = [('x_hand', 'أسمّي الله وأغسل الكفين'), ('x_mouth', 'أتمضمض'), ('x_nose', 'أستنشق الماء وأستنثر'), ('x_eye', 'أغسل الوجه'), ('x_hand', 'أغسل اليدين إلى المرفقين'), ('x_ear', 'أمسح الرأس والأذنين'), ('x_foot', 'أغسل القدمين إلى الكعبين')]
    body = '<p class="ins">هذه خطوات الوضوء بالترتيب:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center;padding:2mm 5mm"><span class="no" style="width:9mm;height:9mm">{i+1}</span>{I(a, 12)}<span style="font-size:14pt;font-weight:700">{t}</span></div>' for i, (a, t) in enumerate(steps))
    P = [('خطوات الوضوء', 'نتعلّم خطوات الوضوء بالترتيب. نغسل غالبًا كل عضو ثلاث مرات.', body, 'ws')]
    sh = shuf([t for _, t in steps], 11)
    P.append(('أرتّب الخطوات', 'رقّم الخطوات من 1 إلى 7 حسب ترتيب الوضوء.', order_rows(sh), 'ws'))
    t = [('نتوضّأ قبل الصلاة.', 'صح'), ('نغسل الرجلين قبل الوجه.', 'خطأ'), ('نمسح الرأس ولا نغسله.', 'صح'), ('نبدأ الوضوء بذكر الله.', 'صح'), ('نغسل اليدين إلى المرفقين.', 'صح'), ('لا نغسل القدمين في الوضوء.', 'خطأ')]
    P.append(('أحكم على العبارة', 'اختر صح أو خطأ.', tf(t), 'ws'))
    key = '<p><b>الترتيب الصحيح:</b></p>' + '<br>'.join(f'{i+1}) {t}' for i, (_, t) in enumerate(steps)) + '<br><br>' + K('صح وخطأ', [a for _, a in t])
    return fin(S('g4-wudu-steps', 'خطوات الوضوء', 'أتعلّم الوضوء وأرتّب خطواته', ['الصف الرابع', 'التربية الإسلامية', 'العبادات', 'مع الحلول'], '#0891b2', '#dcf4fa'), P, key)

def isl5():
    pr = [('الفجر', 2, 'قبل شروق الشمس'), ('الظهر', 4, 'بعد زوال الشمس عن وسط السماء'), ('العصر', 4, 'في وقت العصر بعد الظهر'), ('المغرب', 3, 'عند غروب الشمس'), ('العشاء', 4, 'في الليل بعد المغرب')]
    body = '<p class="ins">أكمل عدد الركعات (الفرض) في الجدول:</p><table><tr><th>الصلاة</th><th>وقتها</th><th style="width:30mm">عدد الركعات</th></tr>' + ''.join(f'<tr><td style="font-weight:700;font-size:14pt">{n}</td><td>{w}</td><td style="text-align:center"><span class="ans" style="min-width:16mm"></span></td></tr>' for n, _, w in pr) + '</table>'
    P = [('الصلوات الخمس', 'نتعلّم أسماء الصلوات وأوقاتها وعدد ركعاتها.', body, 'ws')]
    L = ['صلاة تُؤدّى عند غروب الشمس', 'صلاة تُؤدّى قبل شروق الشمس', 'صلاة تُؤدّى في الليل بعد المغرب']
    R = ['العشاء', 'المغرب', 'الفجر']  # الإجابة: المغرب، الفجر، العشاء
    P.append(('أصِل الصلاة بوقتها', 'صِل كل وصف باسم الصلاة المناسبة.', line_match(L, R), 'ws'))
    total = sum(r for _, r, _ in pr)
    qs = [('كم ركعة في صلاة المغرب؟', ['2', '3', '4'], '3'), ('أيّ صلاة عدد ركعاتها اثنتان؟', ['الفجر', 'الظهر', 'العشاء'], 'الفجر')]
    body = mcq(qs) + f'<div class="bx"><b>3)</b> مجموع ركعات الصلوات الخمس في الفرض = {ans_line(20)} ركعة.</div>'
    P.append(('أختار وأحسب', 'ضع دائرة حول الإجابة الصحيحة ثم احسب المجموع.', body, 'ws'))
    key = K('عدد الركعات', [f'{n}: {r}' for n, r, _ in pr]) + '<p><b>التوصيل:</b> عند غروب الشمس ← المغرب، قبل شروق الشمس ← الفجر، في الليل بعد المغرب ← العشاء.</p>' + K('الاختيار', ['3', 'الفجر']) + f'<p>المجموع = 2 + 4 + 4 + 3 + 4 = {total} ركعة.</p>'
    return fin(S('g5-five-prayers', 'الصلوات الخمس', 'أسماؤها وأوقاتها وعدد ركعاتها', ['الصف الخامس', 'التربية الإسلامية', 'العبادات', 'مع الحلول'], '#7c3aed', '#efe6ff'), P, key)

def isl6():
    mo = ['محرّم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'جمادى الأولى', 'جمادى الآخرة', 'رجب', 'شعبان', 'رمضان', 'شوّال', 'ذو القعدة', 'ذو الحجة']
    body = '<p class="ins">أشهر السنة الهجرية اثنا عشر شهرًا:</p><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:3mm">' + ''.join(f'<div class="q" style="min-height:14mm;font-size:13.5pt;font-weight:700"><span class="no">{i+1}</span>{m}</div>' for i, m in enumerate(mo)) + '</div>'
    P = [('الأشهر الهجرية', 'نقرأ الأشهر الهجرية بالترتيب.', body, 'ws')]
    miss = [(2, 'محرّم'), (4, 'ربيع الآخر'), (7, 'رجب'), (9, 'رمضان'), (12, 'ذو الحجة')]
    mm = [(n, mo[n - 1]) for n in (1, 3, 8, 10, 11)]
    rows = ''.join(f'<tr><td style="text-align:center;width:16mm">{n}</td><td><span class="ans" style="min-width:60mm"></span></td></tr>' for n, _ in mm)
    body = '<p class="ins"><b>أ)</b> اكتب اسم الشهر الذي ترتيبه:</p><table><tr><th>الترتيب</th><th>اسم الشهر</th></tr>' + rows + '</table>'
    body += '<p class="ins" style="margin-top:4mm"><b>ب)</b> أجب:</p><div class="bx">١) الشهر الذي قبل رمضان: ' + ans_line(30) + '<br>٢) الشهر الذي بعد رمضان: ' + ans_line(30) + '<br>٣) أول شهر في السنة الهجرية: ' + ans_line(30) + '</div>'
    P.append(('أكمل الأشهر', 'استعن بالصفحة السابقة.', body, 'ws'))
    L = ['رمضان', 'شوّال', 'ذو الحجة', 'محرّم']; R = ['الحج وعيد الأضحى في العاشر منه', 'أول شهر في السنة الهجرية', 'صيام الشهر كله', 'عيد الفطر في أول يوم منه']
    # إجابات: رمضان→صيام، شوال→عيد الفطر، ذو الحجة→الحج وعيد الأضحى، محرم→أول شهر
    t = [('عدد الأشهر الهجرية اثنا عشر شهرًا.', 'صح'), ('ذو القعدة وذو الحجة ومحرّم ورجب من الأشهر الحُرُم.', 'صح'), ('شعبان يأتي بعد رمضان.', 'خطأ')]
    P.append(('أصِل وأحكم', 'صِل الشهر بمناسبته، ثم حدّد صح أو خطأ.', '<p class="ins"><b>أ)</b> صِل:</p>' + line_match(L, R) + '<p class="ins"><b>ب)</b></p>' + tf(t), 'ws'))
    key = '<p>الأشهر بالترتيب: ' + '، '.join(f'{i+1}) {m}' for i, m in enumerate(mo)) + '</p>' + K('أسماء الأشهر', [m for _, m in mm]) + K('الأسئلة', ['شعبان', 'شوّال', 'محرّم']) + '<p><b>التوصيل:</b> رمضان ← صيام الشهر كله، شوّال ← عيد الفطر في أول يوم منه، ذو الحجة ← الحج وعيد الأضحى في العاشر منه، محرّم ← أول شهر في السنة الهجرية.</p>' + K('صح وخطأ', [a for _, a in t]) + '<p>شعبان يأتي قبل رمضان.</p>'
    return fin(S('g6-hijri-months', 'الأشهر الهجرية', 'أسماؤها وترتيبها ومناسباتها', ['الصف السادس', 'التربية الإسلامية', 'التقويم الهجري', 'مع الحلول'], '#16a34a', '#e0f7e8'), P, key)

# ===== مهارات حياتية =====
def ls1():
    h = [('1f9fc', 'أغسل يديّ بالماء والصابون قبل الأكل وبعد الحمّام', 'صح'), ('1faa5', 'أنظّف أسناني بالفرشاة صباحًا ومساءً', 'صح'), ('x_hand', 'أضع يدي على فمي عندما أسعل', 'صح'), ('x_shoes', 'أدخل البيت بحذائي المتّسخ إلى غرفة النوم', 'خطأ')]
    body = '<p class="ins">انظر إلى الصورة واقرأ العبارة، ثم ضع دائرة حول الإجابة:</p>' + ''.join(f'<div class="bx" style="display:flex;gap:4mm;align-items:center">{I(a, 18)}<div style="flex:1;font-size:13.5pt">{t}<br>{chips(["عادة صحيحة", "عادة خاطئة"])}</div></div>' for a, t, _ in h)
    P = [('عادات النظافة', 'نظافتي تحميني من الأمراض.', body, 'ws')]
    days = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة']
    rows = ''.join(f'<tr><td style="font-weight:700">{d}</td><td style="text-align:center"><span class="opt" style="min-width:10mm;height:9mm"></span></td><td style="text-align:center"><span class="opt" style="min-width:10mm;height:9mm"></span></td><td style="text-align:center"><span class="opt" style="min-width:10mm;height:9mm"></span></td></tr>' for d in days)
    P.append(('جدول نظافتي', 'لوّن المربع كل يوم عندما تفعل العادة.', f'<table><tr><th>اليوم</th><th>غسلت يديّ</th><th>نظّفت أسناني صباحًا</th><th>نظّفت أسناني مساءً</th></tr>{rows}</table>', 'ws'))
    body = '<p class="ins">أكمل الجملة:</p><div class="bx" style="line-height:2.4;font-size:14.5pt">١) أغسل يديّ بـ' + ans_line(26) + ' و' + ans_line(26) + '.<br>٢) أنظّف أسناني ' + ans_line(14) + ' مرات في اليوم.<br>٣) أستحمّ لأن النظافة ' + ans_line(30) + '.</div><p class="ins" style="margin-top:4mm">ارسم أدوات النظافة التي تستعملها:</p><div class="q" style="min-height:60mm"></div>'
    P.append(('أكمل وأرسم', 'استعمل ما تعلّمته.', body, 'ws'))
    key = K('صفحة العادات', [a for *_, a in h]) + '<p>صفحة الجدول: تتابعها الأم أو المعلّمة. صفحة الإكمال: الإجابات تقريبية (الماء والصابون، مرتين، تحميني من الأمراض). الرسم حرّ.</p>'
    return fin(S('g1-personal-hygiene', 'نظافتي الشخصية', 'عادات النظافة وجدول أسبوعي أتابعه', ['الصف الأول', 'المهارات الحياتية', 'النظافة', 'مع الحلول'], '#0891b2', '#dcf4fa'), P, key)

def ls2():
    items = [('1f9f8', 'اللعبة', 'صندوق الألعاب'), ('x_dress', 'الفستان / الثوب', 'الخزانة'), ('1f4d6', 'الكتاب', 'رفّ الكتب'), ('x_shoes', 'الحذاء', 'رفّ الأحذية')]
    places = ['صندوق الألعاب', 'الخزانة', 'رفّ الكتب', 'رفّ الأحذية']
    shp = shuf(places, 9)
    body = '<p class="ins">صِل كل شيء بمكانه الصحيح:</p><div style="display:flex;justify-content:space-between;gap:10mm">' + '<div>' + ''.join(f'<div class="q" style="min-height:26mm;margin-bottom:5mm;flex-direction:column;justify-content:center;gap:1mm;font-size:12pt">{I(a, 16)}{n}</div>' for a, n, _ in items) + '</div><div style="flex:1;border-left:.3mm dotted #b8b0d6;border-right:.3mm dotted #b8b0d6;margin:0 2mm"></div><div>' + ''.join(f'<div class="bx" style="min-height:26mm;margin:0 0 5mm;display:grid;place-items:center;min-width:48mm;font-size:13.5pt;font-weight:700">{p}</div>' for p in shp) + '</div></div>'
    P = [('مكان كل شيء', 'ترتيب الغرفة يبدأ بمعرفة مكان كل شيء.', body, 'ws')]
    steps = ['أرفع الملابس المتّسخة وأضعها في سلّة الغسيل', 'أعيد الألعاب إلى صندوقها', 'أرتّب سريري', 'أنظر إلى غرفتي وأقول: ما أجملها!']
    P.append(('خطوات ترتيب الغرفة', 'رقّم الخطوات من 1 إلى 4 بالترتيب المنطقي (آخر خطوة هي النظر إلى النتيجة).', order_rows(shuf(steps, 4)), 'ws'))
    days = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة']
    rows = ''.join(f'<tr><td style="font-weight:700">{d}</td><td style="text-align:center"><span class="opt" style="min-width:10mm;height:9mm"></span></td><td style="text-align:center"><span class="opt" style="min-width:10mm;height:9mm"></span></td></tr>' for d in days)
    P.append(('جدول ترتيب غرفتي', 'لوّن المربع عندما تنجز العمل.', f'<table><tr><th>اليوم</th><th>رتّبت سريري</th><th>أعدت ألعابي لمكانها</th></tr>{rows}</table>', 'ws'))
    key = K('صفحة التوصيل', [f'{n} ← {p}' for _, n, p in items]) + '<p><b>ترتيب الخطوات:</b> ' + ' ← '.join(f'{i+1}) {s}' for i, s in enumerate(steps)) + '</p><p>صفحة الجدول تتابعها الأم أو المعلّمة. وقد تختلف ترتيبات المنازل؛ المهم أن يكون لكل شيء مكان ثابت.</p>'
    return fin(S('g2-tidy-room', 'أرتّب غرفتي', 'مكان كل شيء وجدول أسبوعي للترتيب', ['الصف الثاني', 'المهارات الحياتية', 'التنظيم', 'مع الحلول'], '#db2777', '#fde4f0'), P, key)

def ls3():
    r = [('أقطع الشارع من الأماكن المخصّصة للمشاة.', 'صح'), ('أركض خلف الكرة إلى الشارع.', 'خطأ'), ('أنظر يمينًا ويسارًا قبل العبور.', 'صح'), ('أربط حزام الأمان في السيارة.', 'صح'), ('ألعب بالقرب من السيارات المتحرّكة.', 'خطأ'), ('أمسك يد الكبير عند عبور الطريق المزدحم.', 'صح')]
    P = [('قواعد السلامة في الطريق', 'اقرأ العبارة وحدّد إن كانت صحيحة أم خاطئة.', tf(r), 'ws')]
    steps = ['أقف عند حافة الرصيف ولا أنزل إلى الشارع', 'أنظر يمينًا ويسارًا وأستمع', 'أعبر بهدوء دون ركض', 'أصل إلى الرصيف الآخر بسلام']
    P.append(('خطوات عبور الشارع', 'رقّم الخطوات من 1 إلى 4.', order_rows(shuf(steps, 8)), 'ws'))
    body = '<p class="ins">إشارة المرور للمشاة: ضع دائرة حول ما تفعله مع كل لون.</p>'
    for c, nm, o, a in [('#dc2626', 'الأحمر', ['أقف', 'أعبر'], 'أقف'), ('#ca8a04', 'الأصفر', ['أركض', 'أنتبه وأستعدّ'], 'أنتبه وأستعدّ'), ('#16a34a', 'الأخضر', ['أنظر ثم أعبر بهدوء', 'أقف إلى الأبد'], 'أنظر ثم أعبر بهدوء')]:
        body += f'<div class="bx" style="display:flex;align-items:center;gap:5mm"><span style="width:16mm;height:16mm;border-radius:50%;background:{c};display:inline-block"></span><b style="font-size:15pt;min-width:22mm">{nm}</b>{chips(o)}</div>'
    body += '<p class="ins" style="margin-top:4mm">اكتب: رقم الطوارئ في بلدي هو ' + ans_line(30) + ' (اسأل أحد الكبار).</p>'
    P.append(('ألوان الإشارة', 'اختر التصرّف الصحيح.', body, 'ws'))
    key = K('صح وخطأ', [a for _, a in r]) + '<p><b>ترتيب العبور:</b> ' + ' ← '.join(f'{i+1}) {s}' for i, s in enumerate(steps)) + '</p>' + K('الإشارة', ['الأحمر: أقف', 'الأصفر: أنتبه وأستعدّ', 'الأخضر: أنظر ثم أعبر بهدوء']) + '<p>رقم الطوارئ يختلف من بلد إلى آخر؛ يكتبه الطالب بمساعدة ولي الأمر.</p>'
    return fin(S('g3-road-safety', 'السلامة في الطريق', 'عبور الشارع وإشارة المرور وحزام الأمان', ['الصف الثالث', 'المهارات الحياتية', 'السلامة', 'مع الحلول'], '#ea580c', '#ffeadb'), P, key)

def ls4():
    nw = [('الماء والغذاء', 'حاجة'), ('الدواء عند المرض', 'حاجة'), ('لعبة جديدة', 'رغبة'), ('الملابس المناسبة للمدرسة', 'حاجة'), ('جهاز ألعاب إضافي', 'رغبة'), ('الحلوى كل يوم', 'رغبة')]
    rows = ''.join(f'<tr><td style="text-align:center;width:12mm">{i+1}</td><td style="font-size:14pt">{w}</td><td style="text-align:center"><span class="opt" style="min-width:12mm;height:9mm"></span></td><td style="text-align:center"><span class="opt" style="min-width:12mm;height:9mm"></span></td></tr>' for i, (w, _) in enumerate(nw))
    P = [('الحاجات والرغبات', 'الحاجة شيء لا نستغني عنه، والرغبة شيء نحبّه ويمكننا الاستغناء عنه. ضع علامة في الخانة المناسبة.', f'<table><tr><th>#</th><th>الشيء</th><th>حاجة</th><th>رغبة</th></tr>{rows}</table>', 'ws')]
    allow, save_per, price = 5, 2, 12
    weeks = -(-price // save_per)
    body = f'<div class="bx" style="line-height:2.2">يحصل سالم على <b>{allow}</b> ريالات كل أسبوع، ويوفّر منها <b>{save_per}</b> ريالان. يريد شراء لعبة ثمنها <b>{price}</b> ريالًا.</div>'
    body += f'<div class="bx"><b>1)</b> كم ريالًا ينفق سالم كل أسبوع؟ {ans_line(30)}<br><b>2)</b> كم ريالًا يوفّر بعد 3 أسابيع؟ {ans_line(30)}<br><b>3)</b> بعد كم أسبوعًا يستطيع شراء اللعبة؟ {ans_line(30)}</div>'
    body += '<p class="ins" style="margin-top:4mm">اكتب هدفًا تريد الادّخار له، وكم تحتاج:</p><div class="ans" style="width:100%"></div>'
    P.append(('أدّخر لهدفي', 'نحسب المبلغ المدّخر وعدد الأسابيع.', body, 'ws'))
    body = '<p class="ins">أكمل جدول مصروفي للأسبوع:</p><table><tr><th>البند</th><th>المبلغ (ريال)</th></tr>' + ''.join(f'<tr><td>{x}</td><td><span class="ans" style="min-width:30mm"></span></td></tr>' for x in ['ما حصلت عليه', 'ما ادّخرته', 'ما أنفقته', 'ما تبقّى معي']) + '</table><p class="ins" style="margin-top:4mm">قاعدة: ما أنفقته = ما حصلت عليه − ما ادّخرته.</p>'
    P.append(('جدول مصروفي', 'استعمله كل أسبوع لتتعلّم تنظيم مالك.', body, 'ws'))
    key = K('حاجة أم رغبة', [a for _, a in nw]) + f'<p>الادّخار: (1) {allow - save_per} ريالات (2) {3 * save_per} ريالات (3) {weeks} أسابيع (لأن {weeks - 1}×{save_per} = {(weeks - 1) * save_per} ريالات لا تكفي و{weeks}×{save_per} = {weeks * save_per} ريالًا). الهدف حرّ.</p><p>الجدول يملؤه الطالب بحسب أرقامه.</p>'
    return fin(S('g4-needs-wants-saving', 'الحاجات والرغبات والادّخار', 'أفرّق بين الحاجة والرغبة وأتعلّم الادّخار', ['الصف الرابع', 'المهارات الحياتية', 'المال', 'مع الحلول'], '#ca8a04', '#fdf3cf'), P, key)

def ls5():
    sc = [('أخذ زميلك قلمك دون أن يستأذنك. ما أفضل تصرّف؟', ['أصرخ عليه', 'أقول له بهدوء: «أنا أحتاج قلمي، من فضلك أعده»', 'آخذ أغراضه انتقامًا'], 'أقول له بهدوء: «أنا أحتاج قلمي، من فضلك أعده»'),
          ('اختلفت مع صديقك على اللعبة. ما أفضل تصرّف؟', ['نبحث عن حلّ يرضينا معًا، مثل أن نلعب بالتناوب', 'أترك اللعب وأغضب', 'أقول له إنه لن يلعب معي أبدًا'], 'نبحث عن حلّ يرضينا معًا، مثل أن نلعب بالتناوب'),
          ('زميلتك تتحدّث وأنت تريدين الكلام. ما أفضل تصرّف؟', ['أقاطعها', 'أنتظر حتى تنتهي ثم أتكلّم', 'أذهب بعيدًا'], 'أنتظر حتى تنتهي ثم أتكلّم')]
    body = ''.join(f'<div class="bx"><b>{i+1})</b> {q}<br>' + '<br>'.join(f'<span class="opt" style="margin:1mm 0">{o}</span>' for o in os_) + '</div>' for i, (q, os_, _) in enumerate(sc))
    P = [('ماذا أفعل؟', 'اختر التصرّف الأنسب في كل موقف.', body, 'ws')]
    steps = ['أهدأ وآخذ نفسًا عميقًا', 'أستمع لما يقوله الآخر دون مقاطعة', 'أعبّر عن شعوري بهدوء', 'نبحث معًا عن حلّ مناسب']
    P.append(('خطوات حلّ الخلاف', 'رقّم الخطوات من 1 إلى 4.', order_rows(shuf(steps, 6)), 'ws'))
    body = '<p class="ins">رسالة «أنا»: أعبّر عن شعوري دون اتّهام. أكمل:</p><div class="bx" style="line-height:2.6;font-size:14pt">«أنا أشعر ' + ans_line(26) + '<br>عندما ' + ans_line(40) + '<br>لأنني ' + ans_line(40) + '<br>وأتمنّى أن ' + ans_line(40) + '»</div><p class="ins" style="margin-top:4mm">مثال: «أنا أشعر بالضيق عندما تقاطعني لأنني لا أكمل فكرتي، وأتمنّى أن تنتظرني حتى أنتهي.»</p>'
    P.append(('رسالة «أنا»', 'اختر موقفًا من يومك واكتب رسالتك.', body, 'ws'))
    key = K('ماذا أفعل؟', [a for *_, a in sc]) + '<p><b>ترتيب الخطوات:</b> ' + ' ← '.join(f'{i+1}) {s}' for i, s in enumerate(steps)) + '</p><p>رسالة «أنا»: الإجابة حرّة، وتُقبل ما دامت تصف الشعور والموقف دون اتّهام.</p>'
    return fin(S('g5-communication-conflict', 'التواصل وحلّ الخلافات', 'الاستماع والتعبير الهادئ وحلّ الخلاف', ['الصف الخامس', 'المهارات الحياتية', 'التواصل', 'مع الحلول'], '#4f46e5', '#e6e7ff'), P, key)

def ls6():
    tasks = [('الواجبات المدرسية', 60), ('مراجعة دروس الغد', 30), ('القراءة', 20), ('اللعب مع الأصدقاء', 45), ('مساعدة الأسرة في البيت', 25)]
    total = sum(m for _, m in tasks); avail = 240
    left = avail - total
    rows = ''.join(f'<tr><td style="font-size:14pt">{t}</td><td style="text-align:center">{ltr(m)} دقيقة</td></tr>' for t, m in tasks)
    body = f'<p class="ins">بعد عودة هند من المدرسة، لديها <b>{avail // 60}</b> ساعات (= {avail} دقيقة) حتى وقت النوم. هذه أعمالها:</p><table><tr><th>العمل</th><th>المدة</th></tr>{rows}</table>'
    body += f'<div class="bx" style="margin-top:4mm"><b>1)</b> مجموع مدد الأعمال = {ans_line(24)} دقيقة.<br><b>2)</b> الوقت المتبقّي = {avail} − المجموع = {ans_line(24)} دقيقة.<br><b>3)</b> هل يكفي الوقت لكل الأعمال؟ {chips(["نعم", "لا"])}</div>'
    P = [('وقتي مسؤوليتي', 'نجمع مدد الأعمال ونحسب الوقت المتبقّي.', body, 'ws')]
    items = ['اللعب مع الأصدقاء', 'الواجبات المدرسية', 'مراجعة دروس الغد', 'مساعدة الأسرة في البيت']
    body = '<p class="ins">رتّب الأعمال بحسب أهميتها وموعد تسليمها: رقّم 1 للأهم أولًا ثم 2 ثم 3 ثم 4. (فكّر: ما الذي يجب أن يُنجز أولًا؟)</p>' + order_rows(shuf(items, 2))
    P.append(('أرتّب أولوياتي', 'نبدأ بالأهم ثم المهم، ونترك المسلّي للنهاية. الترتيب قد يختلف قليلًا بحسب ظروف كل طالب.', body, 'ws'))
    hrs = ['4:00', '4:30', '5:00', '5:30', '6:00', '6:30', '7:00', '7:30']
    rows = ''.join(f'<tr><td style="text-align:center;width:28mm">{ltr(h)}</td><td><span class="ans" style="min-width:100mm"></span></td></tr>' for h in hrs)
    body = '<p class="ins">خطّط لعصر يوم عندك: اكتب ما ستفعله في كل فترة.</p><table><tr><th>الوقت</th><th>العمل</th></tr>' + rows + '</table>'
    P.append(('جدولي اليومي', 'جدول من 4:00 إلى 8:00 مساءً (نصف ساعة لكل خانة).', body, 'ws'))
    key = f'<p>(1) {" + ".join(str(m) for _, m in tasks)} = {total} دقيقة. (2) {avail} − {total} = {left} دقيقة. (3) نعم، يكفي الوقت (الوقت المتبقّي موجب).</p><p>ترتيب الأولويات: الواجبات المدرسية ثم مراجعة دروس الغد ثم مساعدة الأسرة ثم اللعب؛ ويُقبل ترتيب مختلف إذا برّره الطالب. الجدول حرّ.</p>'
    return fin(S('g6-time-management', 'تنظيم الوقت', 'الجمع والمتبقّي والأولويات وجدول يومي', ['الصف السادس', 'المهارات الحياتية', 'إدارة الوقت', 'مع الحلول'], '#7c3aed', '#efe6ff'), P, key)

ALL.update(isl1=isl1, isl2=isl2, isl3=isl3, isl4=isl4, isl5=isl5, isl6=isl6, ls1=ls1, ls2=ls2, ls3=ls3, ls4=ls4, ls5=ls5, ls6=ls6)
